CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE users(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys(token_hash text PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), revoked_at timestamptz);
CREATE TABLE requests(owner_id uuid NOT NULL REFERENCES users(id), operation text NOT NULL, key text NOT NULL, digest text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(owner_id,operation,key));
CREATE TABLE rules(id text PRIMARY KEY, body jsonb NOT NULL);
INSERT INTO rules VALUES ('criteria-v1','{"numeric":"decimal34-half-even","default":"T0","crypto_horizon_hours":72,"atr":"wilder14-last120-v1","price_policy":"asof_last_eligible_trade"}');
CREATE TABLE calls(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), submitted_at timestamptz NOT NULL DEFAULT clock_timestamp(), body jsonb NOT NULL, digest text NOT NULL, original_text text NOT NULL, instrument text, market text, timeframe text, UNIQUE(owner_id,id));
CREATE INDEX calls_time ON calls(owner_id,submitted_at DESC,id DESC);
CREATE INDEX calls_instrument ON calls(owner_id,market,instrument,submitted_at DESC);
CREATE INDEX calls_text ON calls USING gin(original_text gin_trgm_ops);
CREATE TABLE call_state(owner_id uuid NOT NULL, call_id uuid NOT NULL, revision bigint NOT NULL DEFAULT 0, voided boolean NOT NULL DEFAULT false, PRIMARY KEY(owner_id,call_id), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE TABLE attachments(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), sha256 text NOT NULL, mime text NOT NULL, size bigint NOT NULL, width int NOT NULL, height int NOT NULL, uploaded_at timestamptz NOT NULL DEFAULT clock_timestamp(), captured_at timestamptz, kind text NOT NULL CHECK(kind IN ('scene','supplement','reference','query')), UNIQUE(owner_id,id));
CREATE TABLE call_attachments(owner_id uuid NOT NULL, call_id uuid NOT NULL, attachment_id uuid NOT NULL, PRIMARY KEY(owner_id,call_id,attachment_id), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,attachment_id) REFERENCES attachments(owner_id,id));
CREATE TABLE events(sequence bigserial PRIMARY KEY, id uuid NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES users(id), call_id uuid, kind text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE INDEX events_poll ON events(owner_id,sequence);
CREATE TABLE reviews(id uuid PRIMARY KEY, owner_id uuid NOT NULL, call_id uuid NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE TABLE episodes(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), instrument text NOT NULL, market text NOT NULL, anchor_at timestamptz NOT NULL, end_at timestamptz NOT NULL, UNIQUE(owner_id,id));
CREATE TABLE episode_links(id uuid PRIMARY KEY, owner_id uuid NOT NULL, episode_id uuid NOT NULL, call_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('suggested','confirmed','explicit','rejected')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,episode_id) REFERENCES episodes(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE TABLE playbooks(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), parent_id uuid, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,id), FOREIGN KEY(owner_id,parent_id) REFERENCES playbooks(owner_id,id));
CREATE TABLE playbook_events(id uuid PRIMARY KEY, owner_id uuid NOT NULL, playbook_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('candidate','adopted','withdrawn','narrowed')), created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,playbook_id) REFERENCES playbooks(owner_id,id));
CREATE TABLE adoptions(owner_id uuid NOT NULL, call_id uuid NOT NULL, playbook_id uuid NOT NULL, executed text NOT NULL DEFAULT 'unknown' CHECK(executed IN ('yes','no','unknown')), evidence jsonb, PRIMARY KEY(owner_id,call_id,playbook_id), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,playbook_id) REFERENCES playbooks(owner_id,id));
CREATE TABLE tags(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, definition text NOT NULL, aliases text[] NOT NULL DEFAULT '{}', version bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,id), UNIQUE(owner_id,name,version));
CREATE TABLE call_tags(owner_id uuid NOT NULL, call_id uuid NOT NULL, tag_id uuid NOT NULL, phase text NOT NULL CHECK(phase IN ('hot','cold')), PRIMARY KEY(owner_id,call_id,tag_id), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,tag_id) REFERENCES tags(owner_id,id));
CREATE TABLE manifests(id uuid PRIMARY KEY, owner_id uuid NOT NULL, call_id uuid NOT NULL, digest text NOT NULL, body jsonb NOT NULL, UNIQUE(owner_id,id), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE TABLE outcomes(id uuid PRIMARY KEY, owner_id uuid NOT NULL, call_id uuid NOT NULL, claim_no int NOT NULL, manifest_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('original','data_revision','rule_replay')), supersedes uuid, result jsonb NOT NULL, digest text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,call_id,claim_no,kind,digest), FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,manifest_id) REFERENCES manifests(owner_id,id) ON DELETE CASCADE);
CREATE TABLE market_snapshots(id uuid PRIMARY KEY, owner_id uuid NOT NULL, call_id uuid NOT NULL, provider text NOT NULL, market text NOT NULL, instrument text NOT NULL, interval text NOT NULL, asof_at timestamptz NOT NULL, received_at timestamptz NOT NULL, body jsonb NOT NULL, digest text NOT NULL, FOREIGN KEY(owner_id,call_id) REFERENCES calls(owner_id,id) ON DELETE CASCADE);
CREATE TABLE jobs(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, dedupe_key text NOT NULL, body jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed')), attempt int NOT NULL DEFAULT 0, run_after timestamptz NOT NULL DEFAULT now(), lease_owner uuid, lease_until timestamptz, result jsonb, error_code text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,kind,dedupe_key));
CREATE INDEX jobs_ready ON jobs(run_after,created_at) WHERE status IN ('queued','running');
CREATE TABLE embedding_models(id text PRIMARY KEY, dimension int NOT NULL, metadata jsonb NOT NULL);
INSERT INTO embedding_models VALUES ('candle-profile-v1',192,'{"kind":"deterministic_structure","version":"1","requires":"red_green_candles","quality":"baseline_unvalidated"}');
CREATE TABLE image_embeddings(id uuid PRIMARY KEY, owner_id uuid NOT NULL, attachment_id uuid NOT NULL, model_id text NOT NULL REFERENCES embedding_models(id), region jsonb NOT NULL, region_hash text NOT NULL, embedding vector NOT NULL, quality jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,attachment_id,model_id,region_hash), FOREIGN KEY(owner_id,attachment_id) REFERENCES attachments(owner_id,id) ON DELETE CASCADE);
CREATE INDEX embeddings_structure_hnsw ON image_embeddings USING hnsw ((embedding::vector(192)) vector_cosine_ops) WHERE model_id='candle-profile-v1';
CREATE TABLE similarity_sessions(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), body jsonb NOT NULL, results jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,id));
CREATE TABLE similarity_feedback(id uuid PRIMARY KEY, owner_id uuid NOT NULL, session_id uuid NOT NULL, attachment_id uuid NOT NULL, relevant boolean NOT NULL, reason text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,session_id) REFERENCES similarity_sessions(owner_id,id) ON DELETE CASCADE, FOREIGN KEY(owner_id,attachment_id) REFERENCES attachments(owner_id,id) ON DELETE CASCADE);
CREATE TABLE set_snapshots(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), definition jsonb NOT NULL, members jsonb NOT NULL, stats jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(owner_id,id));
CREATE TABLE verdicts(id uuid PRIMARY KEY, owner_id uuid NOT NULL, set_id uuid NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), FOREIGN KEY(owner_id,set_id) REFERENCES set_snapshots(owner_id,id));
CREATE TABLE tombstones(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), entity_type text NOT NULL, deleted_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE outbox(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), dedupe_key text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','sent','failed','delivery_unknown')), UNIQUE(owner_id,dedupe_key));
CREATE FUNCTION reject_evidence_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable evidence; append a new event or revision'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['calls','attachments','events','reviews','manifests','outcomes','market_snapshots','rules','tags','playbooks','episode_links','playbook_events'] LOOP EXECUTE format('CREATE TRIGGER immutable_update BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION reject_evidence_update()',t); END LOOP; END $$;
